UPDATE `user`
SET banned = #{banned},
    ban_reason = #{reason}
WHERE id = #{id}

UPDATE `user`
SET muted_until = #{until},
    ban_reason = #{reason}
WHERE id = #{id}

UPDATE `user`
nickname = #{nickname}, avatar = #{avatar}, email = #{email}, password = #{password}, role = #{role},
WHERE id = #{id}
